    function allowProtectedContent() {
      var tesserato = localStorage.getItem("Member") != 0 ? true : false;
      if (localStorage.getItem("Member") == null) tesserato = false;
      var guid = localStorage.getItem("Guid");
      var member = localStorage.getItem("Member");
      var teacher = localStorage.getItem("Teacher");
      var udg = localStorage.getItem("Udg");
      var acceptProfilation = localStorage.getItem("AcceptProfilation");
      var hashKey = localStorage.getItem("Hashkey");

      $.ajax({
        url: "https://dp-fit-prod-function.azurewebsites.net/api/v6/player/sheet",
        type: "POST",
        dataType: "json",
        async: true,
        data: JSON.stringify({
          cardNumber: cardNumber,
          year: yearNow,
          guid: guid,
          member: member,
          teacher: teacher,
          udg: udg,
          acceptProfilation: acceptProfilation,
          hashKey: hashKey,
        }),
        contentType: "application/json; charset=utf-8",
        beforeSend: function () {
          $(".cc-loading-main").show();
        },
        success: function (data) {
          openAttivita = true;
          playerDetails = data;
          tournamentMatchesTmp = playerDetails.tournamentMatches;
          championshipMatchesTmp = playerDetails.championshipMatches;
          manifestationMatchesTmp = playerDetails.manifestationMatches;
          if (tournamentMatchesTmp == null) tournamentMatchesTmp = [];
          if (championshipMatchesTmp == null) championshipMatchesTmp = [];
          if (manifestationMatchesTmp == null) manifestationMatchesTmp = [];
          tournamentMatches = JSLINQ(tournamentMatchesTmp).OrderByDescending(
            function (item) {
              return item.matchDate;
            }
          );
          championshipMatches = JSLINQ(
            championshipMatchesTmp
          ).OrderByDescending(function (item) {
            return item.matchDate;
          });
          manifestationMatches = JSLINQ(
            manifestationMatchesTmp
          ).OrderByDescending(function (item) {
            return item.matchDate;
          });
          tournamentMatchesGroupedByYear = groupMatchesByField(
            tournamentMatches.items,
            "matchDate",
            true
          );
          championshipMatchesGroupedByYear = groupMatchesByField(
            championshipMatches.items,
            "matchDate",
            true
          );
          manifestationMatchesGroupedByYear = groupMatchesByField(
            manifestationMatches.items,
            "matchDate",
            true
          );
          drawInit(
            tournamentMatchesGroupedByYear,
            championshipMatchesGroupedByYear,
            manifestationMatchesGroupedByYear
          );
          playerDetails = data.player[0];
          $("spn-label-profilation").hide();
          drawTab(yearNow);
        },
        error: function (data) {
          showPopUpDetailsError();
        },
        complete: function () {
          $(".cc-loading-main").hide();
        },
      });
    }

